(() => {
  const d = statsAnual.data ?? [];
  const anios = [...d].sort((a,b) => Number(a.ejercicio) - Number(b.ejercicio));
  const pct = (parte, total) => total ? Number(((Number(parte) / Number(total)) * 100).toFixed(1)) : 0;
  return {
    "tooltip": { "trigger": "axis", "axisPointer": { "type": "shadow" },
                 "formatter": function(p) {
                   return p[0].name + "<br/>" + p.map(s => s.seriesName + ": " + s.value + "%").join("<br/>");
                 } },
    "legend": { "bottom": 0 },
    "grid": { "left": 60, "right": 30, "top": 20, "bottom": 50, "containLabel": true },
    "xAxis": { "type": "value", "max": 100, "axisLabel": { "formatter": "{value}%" } },
    "yAxis": { "type": "category", "data": anios.map(r => String(r.ejercicio)) },
    "series": [
      {
        "name": "FUNDAE",
        "type": "bar",
        "stack": "total",
        "itemStyle": { "color": "#eda100" },
        "label": { "show": true, "formatter": "{c}%" },
        "data": anios.map(r => pct(r.facturado_tripartita, r.total_facturado))
      },
      {
        "name": "Ordinarias",
        "type": "bar",
        "stack": "total",
        "itemStyle": { "color": "#2a78d6" },
        "label": { "show": true, "formatter": "{c}%" },
        "data": anios.map(r => pct(r.facturado_ordinario, r.total_facturado))
      }
    ]
  };
})()
}}

